    37		
    38		private BigInteger factorial_aux(BigInteger n, BigInteger acc) {
    39			if (n.compareTo(BigInteger.ZERO) == -1)
    40				throw new CompilerError("Integer Literal folding: Need to do something for factorial of negative values");
    41			if (n.equals(BigInteger.ZERO))
    42			   	return acc;
    43			else
    44				return factorial_aux(n.subtract(BigInteger.ONE),n.multiply(acc)); 
    45		}
    46		
    47		private BigInteger factorial(BigInteger n) {
    48			return factorial_aux(n,BigInteger.ONE);
    49		}
    50		
    51		private BigInteger choose(BigInteger n, BigInteger k) {
    52			BigInteger n_fact = factorial(n);
    53			BigInteger k_fact = factorial(k);
    54			BigInteger nminusk_fact = factorial(n.subtract(k));
    55			return n_fact.divide(k_fact.multiply(nminusk_fact));
    56		}
    57		
    58		private Node foldBinaryOperator(FunctionalRef op_result, ExprInfo info_result, Expr arg0, Expr arg1) {
    59			
    60			BigInteger v0 = ((IntLiteralExpr)arg0).getIntVal();
    61			BigInteger v1 = ((IntLiteralExpr)arg1).getIntVal();
    62			String op = op_result.toString();
    63			if (op.equals("+") || op.equals("\u229E") || op.equals("\u2214"))  // + BOXPLUS DOTPLUS 
    64				return ExprFactory.makeIntLiteralExpr(info_result,v0.add(v1));
    65			if (op.equals("-") || op.equals("\u229F") || op.equals("\u2238")) // - BOXMINUS DOTMINUS
    66				return ExprFactory.makeIntLiteralExpr(info_result,v0.subtract(v1));
    67			if (op.equals("BY") || op.equals("BOXCROSS") || op.equals("DOTCROSS") || op.equals("DOT") || op.equals("BOXDOT") || op.equals("juxtaposition"))
    68				return ExprFactory.makeIntLiteralExpr(info_result,v0.multiply(v1));
    69			if (op.equals("DIV") && v0.equals(BigInteger.ZERO) && v1.equals(BigInteger.ZERO)) 
    70				return ExprFactory.makeVarRef(info_result.getSpan(),WellKnownNames.compilerBuiltin(),WellKnownNames.UndefinedNumber());
    71			if (op.equals("DIV") && v0.compareTo(BigInteger.ZERO) == -1 && v1.equals(BigInteger.ZERO)) 
    72				return ExprFactory.makeVarRef(info_result.getSpan(),WellKnownNames.compilerBuiltin(),WellKnownNames.NegativeInfinity());
    73			if (op.equals("DIV") && v1.equals(BigInteger.ZERO)) 
    74				return ExprFactory.makeVarRef(info_result.getSpan(),WellKnownNames.compilerBuiltin(),WellKnownNames.Infinity());
    75			if (op.equals("DIV")) 
    76				return ExprFactory.makeIntLiteralExpr(info_result,v0.divide(v1));
    77			if (op.equals("AND"))
    78				return ExprFactory.makeIntLiteralExpr(info_result,v0.and(v1));
    79			if (op.equals("OR"))
    80				return ExprFactory.makeIntLiteralExpr(info_result,v0.or(v1));
    81			if (op.equals("XOR"))
    82				return ExprFactory.makeIntLiteralExpr(info_result,v0.xor(v1));
    83			if (op.equals("MIN"))
    84				return ExprFactory.makeIntLiteralExpr(info_result,v0.min(v1));
    85			if (op.equals("MAX"))
    86				return ExprFactory.makeIntLiteralExpr(info_result,v0.max(v1));
    87			if(op.equals("MINMAX"))
    88				return ExprFactory.makeTupleExpr(info_result.getSpan(), ExprFactory.makeIntLiteralExpr(NodeUtil.getSpan(arg0),v0.min(v1)),ExprFactory.makeIntLiteralExpr(NodeUtil.getSpan(arg1),v0.max(v1)));
    89			if(op.equals("CHOOSE"))
    90				return ExprFactory.makeIntLiteralExpr(info_result.getSpan(),choose(v0,v1));
    91			boolean lt = v0.compareTo(v1) == -1 ? true : false;
    92			boolean gt = v0.compareTo(v1) == 1 ? true : false; 
    93			boolean eq = v0.equals(v1);
    94			if (op.equals("<"))
    95				return ExprFactory.makeBooleanLiteralExpr(info_result,lt);
    96			if (op.equals("<="))
    97				return ExprFactory.makeBooleanLiteralExpr(info_result,lt || eq);
    98			if (op.equals(">"))
    99				return ExprFactory.makeBooleanLiteralExpr(info_result,gt);
   100			if (op.equals(">="))
   101				return ExprFactory.makeBooleanLiteralExpr(info_result,gt || eq);
   102			if (op.equals("=")) 
   103				return ExprFactory.makeBooleanLiteralExpr(info_result, eq);
   104			if (op.equals("NE"))
   105				return ExprFactory.makeBooleanLiteralExpr(info_result, lt || gt);
   106			List<Expr> args = Arrays.asList(arg0,arg1);
   107			return new OpExpr(info_result, op_result, args);
   108			
   109		}
