   111		@Override
   112	    public Node forChainExprOnly(ChainExpr that, ExprInfo info_result, Expr first_result, List<Link> links_result) {
   113	
   114			if (first_result instanceof IntLiteralExpr) {
   115				if (links_result.size() == 0) throw new CompilerError("The list of links is empty");
   116				Link arg = links_result.get(0);
   117				if (arg.getExpr() instanceof IntLiteralExpr) {
   118					Node folded = foldBinaryOperator(arg.getOp(),info_result,first_result,arg.getExpr());
   119					if (links_result.size() == 1)	
   120						return folded;
   121					else {
   122						if (folded instanceof BooleanLiteralExpr)	{
   123							if (((BooleanLiteralExpr) folded).getBooleanVal() == 0) 
   124								return ExprFactory.makeBooleanLiteralExpr(info_result,false);
   125							else {
   126								Expr e = links_result.remove(0).getExpr(); 
   127							    return forChainExprOnly(that,info_result,e,links_result);
   128							}
   129						}
   130						else 
   131							throw new CompilerError("One of the link in a chained expression produced something other than a boolean literal during folding.");
   132						
   133					}
   134				}	
   135				
   136			}
   137			
   138			if (that.getInfo() == info_result && that.getFirst() == first_result && that.getLinks() == links_result) return that;
   139	        return new ChainExpr(info_result, first_result, links_result);
   140	    }
